const STORE='hanama-draft-v1';const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
function makeItem(type,options={}){const a=assetById[type];return {id:uid(),type,x:50,y:65,h:a.height||48,angle:0,trim:0,flip:false,length:1,cuts:[],...options};}
const initial=()=>({version:2,id:uid(),title:L('风经过的地方','Where the Wind Passed'),vessel:'round',scene:'paper',mood:'静寂',generation:'natural',intention:L('像清晨的风掠过庭院，安静、自然，留一点不完美。','Like a morning breeze through the garden: quiet, natural, and gently imperfect.'),items:[makeItem(specimenFor('pine').id,{h:49,angle:-20}),makeItem(specimenFor('calla').id,{h:45,angle:9}),makeItem(specimenFor('chrysanthemum').id,{h:32,angle:28})]});
const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));const clone=o=>JSON.parse(JSON.stringify(o));const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function validate(v){
 if(!v||![1,2].includes(v.version)||!Array.isArray(v.items)||v.items.length>24||!vessels.some(a=>a.id===v.vessel)||!Object.hasOwn(scenes,v.scene))throw Error(L('这不是有效的花间草稿','This is not a valid Hanama draft'));
 let totalPoints=0;const seenIds=new Set();
 return {version:2,id:typeof v.id==='string'&&/^[A-Za-z0-9_-]{1,80}$/.test(v.id)?v.id:uid(),title:String(v.title||L('未命名作品','Untitled Arrangement')).slice(0,40),vessel:v.vessel,scene:v.scene,mood:['静寂','侘寂','春意','野趣'].includes(v.mood)?v.mood:'静寂',generation:['natural','creative','faithful'].includes(v.generation)?v.generation:'natural',intention:String(v.intention||'').slice(0,600),items:v.items.map(i=>{
  if(!specimens.some(a=>a.id===i.type)||!['x','y','h','angle','trim'].every(k=>Number.isFinite(i[k])))throw Error(L('花材信息不完整','Material data is incomplete'));
  const cuts=(Array.isArray(i.cuts)?i.cuts:[]).slice(0,24).map(c=>{
   if(!['lasso','brush'].includes(c.kind)||!Array.isArray(c.points)||c.points.length>128)throw Error(L('剪枝信息不完整','Pruning data is incomplete'));
   totalPoints+=c.points.length;if(totalPoints>8000)throw Error(L('剪枝信息过多','The draft contains too much pruning detail'));
   const points=c.points.map(p=>{if(!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite))throw Error(L('剪枝坐标无效','Pruning coordinates are invalid'));return p.map(n=>clamp(n,-3,4));});
   return {kind:c.kind,points,radius:clamp(Number.isFinite(c.radius)?c.radius:.025,.002,.3)};
  });
  let itemId=typeof i.id==='string'&&/^[A-Za-z0-9_-]{1,100}$/.test(i.id)&&!seenIds.has(i.id)?i.id:uid();seenIds.add(itemId);
  return makeItem(i.type,{id:itemId,x:clamp(i.x,5,95),y:clamp(i.y,15,95),h:clamp(i.h,10,95),angle:clamp(i.angle,-180,180),trim:clamp(i.trim,0,60),flip:!!i.flip,length:clamp(Number.isFinite(i.length)?i.length:1,.6,2.4),cuts});
 })};
}
let state=initial(),selected=null,category='flowers',familyFilter='all',vesselFilter='all',undoStack=[],redoStack=[],toastTimer,images={},galleryUrls=[],importArtFor=null,drag=null,editMode='move',stroke=null,layerDragId=null;
const spriteCache=new Map();
try{const v=localStorage.getItem(STORE);if(v)state=validate(JSON.parse(v))}catch{}
function bytesToBase64(bytes){let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str)}
async function readLimited(stream,max=500000){const reader=stream.getReader(),parts=[];let size=0;try{for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>max)throw Error(L('草稿过大','The draft is too large'));parts.push(value)}}finally{reader.releaseLock()}const out=new Uint8Array(size);let offset=0;for(const part of parts){out.set(part,offset);offset+=part.length}return out}
async function encodeShare(s){const bytes=new TextEncoder().encode(JSON.stringify(s));if(globalThis.CompressionStream){const encoded=await readLimited(new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip')));return '#draft2='+bytesToBase64(encoded).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')}return '#draft='+bytesToBase64(bytes)}
async function decodeShare(hash){const compressed=hash.startsWith('#draft2=');let data=hash.slice(compressed?8:7);if(data.length>30000)throw Error(L('草稿链接过长','The draft link is too long'));if(compressed)data=data.replaceAll('-','+').replaceAll('_','/');let bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));if(compressed){if(!globalThis.DecompressionStream)throw Error(L('请通过草稿文件导入','Import the draft file instead'));bytes=await readLimited(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')))}return validate(JSON.parse(new TextDecoder().decode(bytes)))}
let sharedLoaded=false;
try{if(location.hash.startsWith('#draft=')||location.hash.startsWith('#draft2=')){state=await decodeShare(location.hash);state.id=uid();sharedLoaded=true;history.replaceState(null,'',location.pathname+location.search)}}catch{setTimeout(()=>toast(L('草稿链接无法打开，请用导出的 JSON 文件恢复。','The draft link could not be opened. Restore it from an exported JSON file.')),500)}
selected=state.items.at(-1)?.id||null;

function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));$('#save-state').textContent=L('已自动保存到本机','Auto-saved on this device')}catch{$('#save-state').textContent=L('本机保存不可用，请导出草稿','Local saving is unavailable; please export your draft')}}
function checkpoint(){undoStack.push({state:clone(state),selected});if(undoStack.length>60)undoStack.shift();redoStack=[];renderHistory()}
function renderHistory(){$('#undo-button').disabled=!undoStack.length;$('#redo-button').disabled=!redoStack.length}
function current(){return state.items.find(i=>i.id===selected)}
function specimenCanvas(item,extraCut){
 const key=JSON.stringify([item.type,item.length,item.trim,item.cuts]);
 if(!extraCut&&spriteCache.get(item.id)?.key===key)return spriteCache.get(item.id).canvas;
 if(!images[item.type])return null;
 const canvas=composeSpecimen(images[item.type],item,assetById[item.type],extraCut);
 if(!extraCut)spriteCache.set(item.id,{key,canvas});return canvas;
}
function stemStyle(i){const a=assetById[i.type],g=dimensions(i,a);return `left:${i.x}%;top:${i.y}%;height:${i.h*g.height}%;width:${i.h*g.ratio}%;--anchor:${g.anchor*100}%;transform-origin:${g.anchor*100}% 100%;transform:translate(${-g.anchor*100}%,-100%) rotate(${i.angle}deg) scaleX(${i.flip?-1:1});`}
function drawStemCanvas(el,item,extraCut){const src=specimenCanvas(item,extraCut);if(!src)return;const canvas=$('canvas',el);canvas.width=src.width;canvas.height=src.height;canvas.getContext('2d').drawImage(src,0,0)}
function renderStage(){
 const root=$('#composition');root.innerHTML=state.items.map(i=>{const name=assetName(assetById[i.type]);return `<div class="stem ${i.id===selected?'selected':''}" data-id="${i.id}" style="${stemStyle(i)}" role="button" tabindex="0" aria-label="${esc(L(`${name}，点击选择，拖动调整`,`${name}; click to select and drag to move`))}" aria-pressed="${i.id===selected}"><canvas class="specimen-image" aria-hidden="true"></canvas></div>`}).join('');
 for(const i of state.items){drawStemCanvas($(`.stem[data-id="${i.id}"]`),i)}
 for(const id of spriteCache.keys()){if(!state.items.some(i=>i.id===id))spriteCache.delete(id)}
 $('#vessel').src=assetPath(state.vessel);$('#vessel').alt=assetName(assetById[state.vessel]);const vg=vesselGeometry(assetById[state.vessel]);$('#vessel').style.height=vg.height+'%';$('#vessel').style.width=vg.width+'%';$('#stage').dataset.scene=state.scene;
 $$('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene===state.scene));$('#study-count').textContent=String(state.items.length).padStart(3,'0');renderSelection();renderHistory();renderLayerList();drawPruneOverlay();
}
function renderSelection(){
 let i=current();$('#selected-empty').hidden=!!i;$('#selection-controls').hidden=!i;if(!i){setEditMode('move');return;}
 const a=assetById[i.type];$('#selected-thumb').src=assetPath(i.type);$('#selected-thumb').alt=assetName(a);$('#selected-name').textContent=assetName(a);$('#variant-label').textContent=`${assetColor(a)} · ${assetPose(a)}`;
 $('#angle').value=i.angle;$('#size').value=i.h;$('#trim').value=i.trim;$('#length').value=Math.round((i.length??1)*100);
 $('#angle-value').value=i.angle+'°';$('#size-value').value=Math.round(i.h/a.height*100)+'%';$('#trim-value').value=i.trim+'%';$('#length-value').value=Math.round((i.length??1)*100)+'%';$('#restore-cuts').disabled=!i.cuts?.length;
}
const generationDescriptions={zh:{natural:'构图、数量和光影不变，只让花瓣内部自然错落并带少量微小偏色。',creative:'保持所有结构不动，花瓣卷边、开放程度和局部色差更明显。',faithful:'保持所有结构不动，只加入最轻微的花瓣不对称与自然瑕疵。'},en:{natural:'Keep composition, count, and lighting fixed; vary only internal petal form and tiny pigment shifts.',creative:'Keep all structure fixed; make petal curl, opening stage, and local color variation more visible.',faithful:'Keep all structure fixed; add only the faintest petal asymmetry and natural imperfections.'}};
function renderAll(){applyLanguage();renderStage();renderMaterials();setEditMode(editMode);$('#work-title').value=state.title;$('#intention').value=state.intention;$$('[data-mood]').forEach(b=>b.classList.toggle('active',b.dataset.mood===state.mood));$('#generation-mode').value=state.generation||'natural';$('#generation-mode-help').textContent=generationDescriptions[lang][state.generation||'natural'];persist()}
function addSpecimen(type,placement='front'){if(state.items.length>=24)return toast(L('先让这 24 枝找到自己的位置，再添加。','Arrange these 24 stems before adding another.'));checkpoint();const insertion=vesselGeometry(assetById[state.vessel]).insertion,item=makeItem(type,{x:insertion[0],y:insertion[1],angle:0});if(placement==='back')state.items.unshift(item);else state.items.push(item);selected=item.id;setEditMode('move');renderStage();persist();const name=assetName(assetById[type]);toast(L(`添入一枝${name}，放在${placement==='back'?'最后层':'最前层'}`,`Added ${name} to the ${placement==='back'?'back':'front'} layer`))}
function variantPicker(family,replaceId=null){
 const options=specimens.filter(a=>a.family===family).sort((a,b)=>Number(legacyFlowers.includes(a))-Number(legacyFlowers.includes(b)));
 const selectedType=state.items.find(i=>i.id===replaceId)?.type;
 let placement='front';
 const placementChoice=replaceId?'':`<fieldset class="insert-position"><legend>${L('加入画布的位置','Place on canvas')}</legend><button type="button" class="active" data-insert-position="front" aria-pressed="true"><strong>${L('最前层','Front layer')}</strong><small>${L('盖在现有花材前','In front of existing materials')}</small></button><button type="button" data-insert-position="back" aria-pressed="false"><strong>${L('最后层','Back layer')}</strong><small>${L('Behind existing materials')}</small></button></fieldset>`;
 openModal(`<h2>${esc(L(`${assetName(options[0])}，选一枝喜欢的。`,`Choose a ${assetName(options[0])} specimen.`))}</h2><p>${L('选择自然花色与花面姿态。整枝的倾斜角度仍可在画布里自由调整。','Choose a natural color and flower-facing pose. You can still adjust the whole stem angle on the canvas.')}</p>${placementChoice}<div class="variant-grid">${options.map(a=>`<button class="variant-card ${a.id===selectedType?'active':''}" data-variant="${a.id}"><img src="${assetPath(a.id)}" alt="${esc(assetColor(a)+' '+assetPose(a))}"><strong><i style="background:${a.swatch}"></i>${esc(assetColor(a))}</strong><span>${esc(assetPose(a))}</span></button>`).join('')}</div>${replaceId&&current()?.cuts.length?`<p class="file-note">${L('换姿态会恢复这枝的剪口，便于重新修剪；可以撤销恢复。','Changing pose restores this stem before pruning so you can trim it again; Undo remains available.')}</p>`:''}`,'BOTANICAL VARIATIONS');
 $$('[data-insert-position]').forEach(b=>b.onclick=()=>{placement=b.dataset.insertPosition;$$('[data-insert-position]').forEach(t=>{const on=t===b;t.classList.toggle('active',on);t.setAttribute('aria-pressed',String(on))})});
 $$('[data-variant]').forEach(b=>b.onclick=()=>{if(replaceId){const i=state.items.find(i=>i.id===replaceId);if(!i)return;if(i.type!==b.dataset.variant){checkpoint();i.type=b.dataset.variant;i.cuts=[];spriteCache.delete(i.id);selected=i.id;renderStage();persist()}}else addSpecimen(b.dataset.variant,placement);$('#modal').close()});
}
$('#change-variant').onclick=()=>{const i=current();if(i)variantPicker(assetById[i.type].family,i.id)};
function renderMaterials(){
 const materials=category==='flowers'?flowers.filter(a=>familyFilter==='all'||a.group===familyFilter):vessels.filter(a=>vesselFilter==='all'||a.group===vesselFilter);
 $('#material-filters').hidden=category!=='flowers';$('#vessel-filters').hidden=category!=='vessels';$('#material-heading').textContent=category==='flowers'?L('一枝一叶','Botanicals'):L('一器一境','Vessels');$('#material-count').textContent=category==='flowers'?L(`${flowers.length} 种 · ${specimens.length} 款`,`${flowers.length} types · ${specimens.length} variants`):L(`${vessels.length} 款花器`,`${vessels.length} vessels`);
 $('#material-grid').innerHTML=materials.map(a=>{const sample=category==='flowers'?specimenFor(a.id):a,name=assetName(a);return `<button class="material-card ${category==='vessels'&&a.id===state.vessel?'active':''}" data-material="${a.id}" aria-label="${esc(L(`${category==='flowers'?'挑选':'选择'}${name}`,`${category==='flowers'?'Choose':'Select'} ${name}`))}"><span class="add-mark">${category==='flowers'?'+':''}</span><img src="${assetPath(sample.id)}" alt="${esc(name)}" draggable="false" loading="lazy"><strong>${esc(lang==='en'?(a.en||a.name):(a.shortName||a.name))}</strong><small>${category==='flowers'?L(`${a.variants} 款可选`,`${a.variants} variants`):esc(assetColor(a))}</small></button>`}).join('');
 $('#material-grid').onclick=e=>{const b=e.target.closest('[data-material]');if(!b)return;const type=b.dataset.material;if(category==='vessels'){if(state.vessel===type)return;checkpoint();const from=vesselGeometry(assetById[state.vessel]).insertion,to=vesselGeometry(assetById[type]).insertion;state.items.forEach(i=>{i.x=clamp(i.x+to[0]-from[0],5,95);i.y=clamp(i.y+to[1]-from[1],15,95)});state.vessel=type;renderStage();renderMaterials();persist();const name=assetName(assetById[type]);toast(L(`已换成${name}`,`Changed to ${name}`))}else variantPicker(type)};
}
$$('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;$$('[data-category]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));renderMaterials()});
$$('[data-vessel-group]').forEach(b=>b.onclick=()=>{vesselFilter=b.dataset.vesselGroup;$$('[data-vessel-group]').forEach(t=>t.classList.toggle('active',t===b));renderMaterials()});
$$('[data-family-group]').forEach(b=>b.onclick=()=>{familyFilter=b.dataset.familyGroup;$$('[data-family-group]').forEach(t=>t.classList.toggle('active',t===b));renderMaterials()});
function pointerStage(e){const r=$('#stage').getBoundingClientRect();return [(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]}
function selectItem(id){selected=id;$$('.stem').forEach(n=>{const on=n.dataset.id===id;n.classList.toggle('selected',on);n.setAttribute('aria-pressed',String(on))});renderSelection()}
function renderLayerList(){
 const list=$('#layer-list');if(!list)return;
 const frontFirst=[...state.items].reverse();
 list.innerHTML=frontFirst.length?frontFirst.map((item,index)=>{const a=assetById[item.type],name=assetName(a),layer=index===0?L('最前层','Front layer'):index===frontFirst.length-1?L('最后层','Back layer'):L(`第 ${index+1} 层`,`Layer ${index+1}`);return `<div class="layer-row ${item.id===selected?'active':''}" data-layer-id="${item.id}" draggable="true"><span class="layer-grip" aria-hidden="true">⠿</span><button class="layer-select" data-layer-select="${item.id}" aria-label="${esc(L(`选择${name}`,`Select ${name}`))}"><img src="${assetPath(item.type)}" alt=""><span><strong>${esc(name)}</strong><small>${layer}</small></span></button><span class="layer-step"><button data-layer-shift="front" aria-label="${esc(L(`将${name}上移一层`,`Move ${name} forward one layer`))}" ${index===0?'disabled':''}>↑</button><button data-layer-shift="back" aria-label="${esc(L(`将${name}下移一层`,`Move ${name} back one layer`))}" ${index===frontFirst.length-1?'disabled':''}>↓</button></span></div>`}).join(''):`<div class="layer-empty">${L('先添入花材，再安排层次。','Add a material, then arrange its layer.')}</div>`;
}
function closeLayerMenu(){const menu=$('#layer-menu');if(menu.hidden)return;menu.hidden=true;$('#layers-tool').setAttribute('aria-expanded','false');layerDragId=null}
function openLayerMenu(clientX,clientY){
 const menu=$('#layer-menu'),stage=$('#stage'),rect=stage.getBoundingClientRect();setEditMode('move');menu.hidden=false;$('#layers-tool').setAttribute('aria-expanded','true');renderLayerList();
 const width=menu.offsetWidth||240,height=menu.offsetHeight||300;const x=Number.isFinite(clientX)?clientX-rect.left:rect.width-width-14;const y=Number.isFinite(clientY)?clientY-rect.top:54;menu.style.left=clamp(x,10,Math.max(10,rect.width-width-10))+'px';menu.style.top=clamp(y,10,Math.max(10,rect.height-height-10))+'px';
}
function shiftLayer(id,direction){
 const index=state.items.findIndex(i=>i.id===id),next=index+(direction==='front'?1:-1);if(index<0||next<0||next>=state.items.length)return;checkpoint();[state.items[index],state.items[next]]=[state.items[next],state.items[index]];selected=id;renderStage();persist();toast(direction==='front'?L('已向前移动一层','Moved forward one layer'):L('已向后移动一层','Moved back one layer'));
}
function applyLayerDrop(id,targetId,after){
 if(!id||id===targetId)return;const frontFirst=[...state.items].reverse(),dragged=frontFirst.find(i=>i.id===id);if(!dragged)return;const without=frontFirst.filter(i=>i.id!==id),targetIndex=without.findIndex(i=>i.id===targetId);if(targetIndex<0)return;checkpoint();without.splice(targetIndex+(after?1:0),0,dragged);state.items=without.reverse();selected=id;renderStage();persist();toast(L('花材层次已调整','Material layers updated'));
}
$('#layer-list').addEventListener('click',e=>{const row=e.target.closest('[data-layer-id]');if(!row)return;const shift=e.target.closest('[data-layer-shift]');if(shift){shiftLayer(row.dataset.layerId,shift.dataset.layerShift);return}if(e.target.closest('[data-layer-select]')){selectItem(row.dataset.layerId);renderLayerList()}});
$('#layer-list').addEventListener('dragstart',e=>{const row=e.target.closest('[data-layer-id]');if(!row)return;layerDragId=row.dataset.layerId;row.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',layerDragId)});
$('#layer-list').addEventListener('dragover',e=>{const row=e.target.closest('[data-layer-id]');if(!row||row.dataset.layerId===layerDragId)return;e.preventDefault();const after=e.clientY>row.getBoundingClientRect().top+row.offsetHeight/2;$$('.layer-row').forEach(n=>n.classList.remove('drop-before','drop-after'));row.classList.add(after?'drop-after':'drop-before');e.dataTransfer.dropEffect='move'});
$('#layer-list').addEventListener('drop',e=>{const row=e.target.closest('[data-layer-id]');if(!row)return;e.preventDefault();const after=row.classList.contains('drop-after'),id=layerDragId||e.dataTransfer.getData('text/plain');applyLayerDrop(id,row.dataset.layerId,after);layerDragId=null});
$('#layer-list').addEventListener('dragend',()=>{layerDragId=null;$$('.layer-row').forEach(n=>n.classList.remove('dragging','drop-before','drop-after'))});
$('#stage').addEventListener('contextmenu',e=>{e.preventDefault();const stem=e.target.closest('.stem');if(stem)selectItem(stem.dataset.id);openLayerMenu(e.clientX,e.clientY)});
$('#layers-tool').onclick=()=>$('#layer-menu').hidden?openLayerMenu():closeLayerMenu();$('#close-layers').onclick=closeLayerMenu;
document.addEventListener('pointerdown',e=>{if(!$('#layer-menu').hidden&&!e.target.closest('#layer-menu')&&!e.target.closest('#layers-tool'))closeLayerMenu()});
$('#composition').addEventListener('pointerdown',e=>{
 if(e.button!==0||editMode!=='move')return;const el=e.target.closest('.stem');if(!el)return;e.preventDefault();selectItem(el.dataset.id);const item=current();drag={pointer:e.pointerId,item,startX:e.clientX,startY:e.clientY,x:item.x,y:item.y,rect:$('#stage').getBoundingClientRect(),el,started:false};el.focus({preventScroll:true});el.setPointerCapture(e.pointerId);
});
$('#composition').addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;if(!drag.started&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<3)return;if(!drag.started){checkpoint();drag.started=true}drag.item.x=clamp(drag.x+(e.clientX-drag.startX)/drag.rect.width*100,5,95);drag.item.y=clamp(drag.y+(e.clientY-drag.startY)/drag.rect.height*100,15,95);drag.el.style.cssText=stemStyle(drag.item)});
function finishDrag(e){if(!drag||drag.pointer!==e.pointerId)return;drag=null;persist()}
$('#composition').addEventListener('pointerup',finishDrag);$('#composition').addEventListener('pointercancel',finishDrag);
function setEditMode(mode){if(mode!=='move'&&!current()){toast(L('先选中要修剪的那一枝。','Select the stem you want to prune first.'));return}editMode=mode;stroke=null;$('#stage').dataset.tool=mode;$('#move-tool').setAttribute('aria-pressed',String(mode==='move'));$('#prune-tool').setAttribute('aria-pressed',String(mode==='lasso'));$$('[data-prune]').forEach(b=>b.classList.toggle('active',b.dataset.prune===mode));$('#brush-setting').hidden=mode!=='brush';$('#stage-hint').textContent=mode==='lasso'?L('圈住不要的枝叶，松手剪掉 · Esc 退出','Circle unwanted foliage and release to cut · Esc to exit'):mode==='brush'?L('涂抹剪掉细节 · Esc 退出','Brush over details to remove · Esc to exit'):L('拖动花材 · 右键调层次','Drag materials · Right-click for layers');$('#prune-help').textContent=mode==='move'?L('先选中一枝，再圈住不要的枝叶。','Select a stem, then circle the foliage to remove.'):mode==='lasso'?L('在画布上围着多余的枝叶画一圈。只修剪当前选中的一枝。','Draw around extra foliage. Only the selected stem will be pruned.'):L('在枝叶上涂抹去除细节。只修剪当前选中的一枝。','Brush over foliage details. Only the selected stem will be pruned.');drawPruneOverlay()}
$('#move-tool').onclick=()=>setEditMode('move');$('#prune-tool').onclick=()=>setEditMode(editMode==='lasso'?'move':'lasso');$$('[data-prune]').forEach(b=>b.onclick=()=>setEditMode(editMode===b.dataset.prune?'move':b.dataset.prune));
$('#brush-size').oninput=e=>$('#brush-value').value=e.target.value;
$('#restore-cuts').onclick=()=>{if(!current()?.cuts.length)return;checkpoint();current().cuts=[];renderStage();persist();toast(L('这枝已恢复到修剪前。','This stem has been restored to its unpruned state.'))};
function drawPruneOverlay(){const c=$('#prune-overlay');if(!c)return;const size=Math.max(1,Math.round($('#stage').getBoundingClientRect().width));c.width=c.height=size;const ctx=c.getContext('2d');if(!stroke?.points.length||!current())return;const item=current(),asset=assetById[item.type];ctx.beginPath();stroke.points.forEach((p,k)=>{const q=sourceToStage(p,item,asset);ctx[k?'lineTo':'moveTo'](q[0]*size,q[1]*size)});ctx.strokeStyle='#a5533e';ctx.lineWidth=2;ctx.setLineDash([5,4]);if(stroke.kind==='lasso'){ctx.closePath();ctx.fillStyle='#a5533e22';ctx.fill()}ctx.stroke();}
new ResizeObserver(()=>{drawPruneOverlay();if(!$('#layer-menu').hidden)openLayerMenu()}).observe($('#stage'));
$('#stage').addEventListener('pointerdown',e=>{if(editMode==='move'||e.button!==0||!current())return;e.preventDefault();if(current().cuts.length>=24)return toast(L('这枝已有 24 处剪口；可恢复剪枝后重剪。','This stem already has 24 cuts. Restore it before pruning again.'));const total=state.items.reduce((n,i)=>n+i.cuts.reduce((m,c)=>m+c.points.length,0),0);if(total>7800)return toast(L('剪枝细节已很多，请先恢复部分剪口。','There is extensive pruning detail. Restore some cuts first.'));const item=current(),p=stageToSource(pointerStage(e),item,assetById[item.type]);stroke={kind:editMode,points:[p],radius:clamp(Number($('#brush-size').value)/$('#stage').getBoundingClientRect().width/(item.h/100)/2,.002,.3),pointer:e.pointerId};$('#stage').setPointerCapture(e.pointerId);drawPruneOverlay()});
$('#stage').addEventListener('pointermove',e=>{if(!stroke||stroke.pointer!==e.pointerId)return;const item=current();const p=stageToSource(pointerStage(e),item,assetById[item.type]);const previous=sourceToStage(stroke.points.at(-1),item,assetById[item.type]),next=pointerStage(e);if(Math.hypot(next[0]-previous[0],next[1]-previous[1])<.003)return;stroke.points.push(p);if(stroke.points.length>512)stroke.points=simplifyPoints(stroke.points,256);if(stroke.kind==='brush')drawStemCanvas($(`.stem[data-id="${item.id}"]`),item,stroke);drawPruneOverlay()});
function finishPrune(e,cancel=false){if(!stroke||stroke.pointer!==e.pointerId)return;const cut=stroke;stroke=null;if(!cancel&&(cut.kind==='brush'||cut.points.length>=3)){checkpoint();current().cuts.push({kind:cut.kind,points:simplifyPoints(cut.points),radius:clamp(cut.radius,.002,.3)});persist();toast(L('已剪去选中的枝叶，可撤销。','Selected foliage removed. You can undo this action.'))}renderStage()}
$('#stage').addEventListener('pointerup',e=>finishPrune(e));$('#stage').addEventListener('pointercancel',e=>finishPrune(e,true));
$('#stage').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeLayerMenu();setEditMode('move');renderStage();return}if(e.target.closest('input,textarea'))return;if(e.key==='Enter'&&e.target.closest('.stem')){selectItem(e.target.closest('.stem').dataset.id);return}const item=current();if(!item)return;if(['Delete','Backspace'].includes(e.key)){e.preventDefault();removeSelected();return}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();checkpoint();const step=e.shiftKey?2:.5;item.x=clamp(item.x+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),5,95);item.y=clamp(item.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0),15,95);const el=$(`.stem[data-id="${item.id}"]`);if(el)el.style.cssText=stemStyle(item);persist()});
for(const [id,key,factor] of [['angle','angle',1],['size','h',1],['trim','trim',1],['length','length',.01]]){let active=false;const el=$('#'+id);el.addEventListener('input',()=>{const item=current();if(!item)return;if(!active){checkpoint();active=true}item[key]=+el.value*factor;renderStage();persist()});el.addEventListener('change',()=>active=false);el.addEventListener('blur',()=>active=false)}
function removeSelected(){if(!current())return;checkpoint();state.items=state.items.filter(i=>i.id!==selected);selected=state.items.at(-1)?.id||null;setEditMode('move');renderStage();persist()}
$('#delete-button').onclick=removeSelected;$('#flip-button').onclick=()=>{if(!current())return;checkpoint();current().flip=!current().flip;renderStage();persist()};$('#layer-button').onclick=()=>{let item=current();if(!item)return;checkpoint();state.items=state.items.filter(i=>i.id!==selected);state.items.push(item);renderStage();persist();toast(L('已移到最前层','Moved to the front layer'))};
$('#undo-button').onclick=()=>{if(!undoStack.length)return;redoStack.push({state:clone(state),selected});const previous=undoStack.pop();state=previous.state;selected=previous.selected;setEditMode('move');renderAll()};$('#redo-button').onclick=()=>{if(!redoStack.length)return;undoStack.push({state:clone(state),selected});const next=redoStack.pop();state=next.state;selected=next.selected;setEditMode('move');renderAll()};
$('#guide-button').onclick=()=>{const on=$('#guide').hidden;$('#guide').hidden=!on;$('#guide-button').setAttribute('aria-pressed',String(on))};$('#reset-button').onclick=()=>{checkpoint();state.items=[];selected=null;setEditMode('move');renderStage();persist();toast(L('花器已留空，随时可以撤销。','The vessel is empty. You can undo this action.'))};
$$('[data-scene]').forEach(b=>b.onclick=()=>{checkpoint();state.scene=b.dataset.scene;renderStage();persist()});$$('[data-mood]').forEach(b=>b.onclick=()=>{checkpoint();state.mood=b.dataset.mood;$$('[data-mood]').forEach(t=>t.classList.toggle('active',t===b));persist()});
$('#work-title').addEventListener('input',e=>{state.title=e.target.value;persist()});$('#intention').addEventListener('input',e=>{state.intention=e.target.value;persist()});
$('#generation-mode').onchange=e=>{checkpoint();state.generation=e.target.value;$('#generation-mode-help').textContent=generationDescriptions[lang][state.generation];persist()};

function openModal(html,kicker='HANAMA ATELIER'){$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=html;icons($('#modal'));if(!$('#modal').open)$('#modal').showModal()}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
function help(){const html=lang==='en'?`<h2>Take a moment and arrange slowly.</h2><div class="step-list"><div><span class="step-number">01</span><p><strong>Choose and place.</strong><br>Select plants and a vessel. Choose a natural color and pose, then place new material at the front or back. Drag to move; right-click the canvas or open Layers to reorder. Size and stem length adjust independently, and the pruning tools remove selected foliage.</p></div><div><span class="step-number">02</span><p><strong>Set your intention.</strong><br>Choose the scene and add a note. All three generation modes lock your flower count, composition, layers, negative space, and lighting. They differ only in how strongly petals vary inside each existing flower head.</p></div><div><span class="step-number">03</span><p><strong>From draft to artwork.</strong><br>Download the pack, upload both draft.png and composition-guide.png to ChatGPT image creation or GPT Image, and paste prompt.txt. Import the result into My Works to save or share it.</p></div></div><p class="file-note">Keyboard: use arrow keys to nudge, Shift + arrows for larger moves, and Delete to remove the selected material. Drafts and artworks stay in this browser unless you export them.</p><div class="modal-actions"><button class="button dark" id="help-done">Start arranging</button><button class="button outline" id="help-import">Import draft file</button></div>`:`<h2>给自己一刻，慢慢插花。</h2><div class="step-list"><div><span class="step-number">01</span><p><strong>选花，落枝。</strong><br>点选左侧花材和花器。挑选自然花色与姿态，并决定新花材放在最前层或最后层。拖动调整位置；右键画布或点击图层按钮可以调整前后顺序。花材大小和枝梗长度可分别调整，也可以圈选剪枝或细部擦除。</p></div><div><span class="step-number">02</span><p><strong>写下你的意境。</strong><br>选择光与景，留下一句话。三种生成方式都会锁定花朵数量、构图、层级、留白和整体光影，区别只在于现有花头内部的花瓣变化强弱。</p></div><div><span class="step-number">03</span><p><strong>从草稿，到作品。</strong><br>下载创作包，在 ChatGPT 图片创作或 GPT Image 中同时上传 draft.png 与 composition-guide.png，再粘贴 prompt.txt。生成后可导入「我的作品」保存或分享。</p></div></div><p class="file-note">键盘操作：方向键微调，Shift + 方向键大幅移动，Delete 删除。草稿与成品仅保存在当前浏览器，导出文件可以备份。</p><div class="modal-actions"><button class="button dark" id="help-done">开始这一枝</button><button class="button outline" id="help-import">导入草稿文件</button></div>`;openModal(html);$('#help-done').onclick=()=>$('#modal').close();$('#help-import').onclick=()=>$('#draft-upload').click()}
$('#help-button').onclick=help;
function sources(){const html=lang==='en'?`<h2>Materials from nature, ideas from ikebana.</h2><p>Hanama is a free-form creative exercise. It does not score work or present its simplified composition hints as school rules.</p><h3>Ikebana references</h3><div class="source-list"><a href="https://chs.ikenobo.jp/about/style.html" target="_blank" rel="noopener noreferrer">Ikenobo · Three styles of ikebana ↗</a><br><a href="https://www.sogetsu.or.jp/e/begin/" target="_blank" rel="noopener noreferrer">Sogetsu · Learning through free expression ↗</a></div><p>Ikenobo free style values the form and texture of plants; Sogetsu encourages personal expression. The spacing and direction cues here are creative suggestions for the game.</p><h3>Asset notes</h3><p>Plant variants and newer vessels are original GPT Image assets. Two original vessels come from <a href="https://purepng.com/photo/18638/objects-vase" target="_blank" rel="noopener noreferrer">PurePNG / PNGStock</a>, marked CC0 on the source page. The inspiration photograph is Rémi Jouan's <a href="https://commons.wikimedia.org/wiki/File:Ikebana_International_Paris_2019_(01).JPG" target="_blank" rel="noopener noreferrer">Ikebana International Paris 2019 (01)</a>, used under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>.</p><p class="file-note">Sources reviewed September 2026. You control exports and sharing; Hanama does not publish your images automatically.</p>`:`<h2>从自然取材，从花道取意。</h2><p>花间以自由创作练习为出发点，不为作品打分，也不将简化的构图方法当作流派规范。</p><h3>花道参考</h3><div class="source-list"><a href="https://chs.ikenobo.jp/about/style.html" target="_blank" rel="noopener noreferrer">池坊 · 花道的三种样式 ↗</a><br><a href="https://www.sogetsu.or.jp/e/begin/" target="_blank" rel="noopener noreferrer">草月 · 自由表达与学习 ↗</a></div><p>池坊的自由花重视草木的形状与质感；草月鼓励创作者表达自己的想法。这里的留白、方向和疏密提示，是游戏中的创作建议。</p><h3>素材说明</h3><p>花枝与自然花色、姿态素材使用 GPT Image 原创生成。新增花器也使用 GPT Image 原创生成；原有两只花器来自 <a href="https://purepng.com/photo/18638/objects-vase" target="_blank" rel="noopener noreferrer">PurePNG / PNGStock</a>，来源页标注 CC0。灵感摄影为 Rémi Jouan 的 <a href="https://commons.wikimedia.org/wiki/File:Ikebana_International_Paris_2019_(01).JPG" target="_blank" rel="noopener noreferrer">Ikebana International Paris 2019 (01)</a>，依据 <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> 使用。</p><p class="file-note">资料整理：2026 年 9 月。你的作品由你导出和分享；本工房不自动公开上传图片。</p>`;openModal(html,'REFERENCES & MATERIALS')}
$('#sources-button').onclick=sources;
async function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error(L('图片暂时无法载入，请稍后重试','The image could not be loaded. Please try again.')));img.src=src})}
const imageTasks=new Map();
function ensureAsset(id){if(images[id])return Promise.resolve(images[id]);if(!imageTasks.has(id)){imageTasks.set(id,loadImage(assetPath(id)).then(img=>{images[id]=img;return img}).catch(err=>{imageTasks.delete(id);throw err}))}return imageTasks.get(id)}
const assetsReady=Promise.allSettled(allAssets.map(a=>ensureAsset(a.id)));
assetsReady.then(results=>{renderStage();if(results.some(r=>r.status==='rejected'))toast(L('部分花材未载入；已载入的花材仍可使用。','Some materials did not load; the available materials can still be used.'))});
