 $('#copy-prompt').onclick=()=>copyText(promptText);
 $('#download-package').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const readme='花间 · 花瓣自然化创作包 / HANAMA · PETAL NATURALIZATION PACK\n\n中文\n1. 同时上传 draft.png 与 composition-guide.png，再粘贴 prompt.txt。\n2. draft.png 锁定花材数量、所有花朵、位置、枝条、层级、留白与整体光影；若参考有差异，以 draft.png 为准。\n3. 随机因子只改变现有花头内部的花瓣偏心、开放程度、微小瑕疵与局部偏色，不能减花、移花或重新打光。\n4. composition.json 可以恢复编辑。\n\nENGLISH\n1. Upload draft.png and composition-guide.png together, then paste prompt.txt.\n2. draft.png locks every material, visible flower, position, stem, layer, gap, and the complete lighting design; it wins if the references differ.\n3. Random factors affect only internal petal eccentricity, opening stage, tiny flaws, and localized pigment. They must not remove or move flowers or relight the scene.\n4. composition.json restores the editable draft.\n\nThe website does not call a generation API and the pack contains no API key.';const zip=await zipFiles([['draft.png',await canvasBlob(draft)],['composition-guide.png',await canvasBlob(guide)],['prompt.txt',new Blob([promptText],{type:'text/plain;charset=utf-8'})],['composition.json',new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'})],['readme.txt',new Blob([readme],{type:'text/plain;charset=utf-8'})]]);download(zip,fileTitle(snapshot)+'-'+L('花瓣自然化创作包','petal-naturalization-pack')+'.zip');toast(L('创作包已下载，请同时上传两张参考图。','Pack downloaded. Upload both reference images together.'))}catch(err){toast(err.message)}finally{b.disabled=false}};
